  // body
  ctx.fillStyle = c.body; ctx.beginPath(); ctx.ellipse(0, 6, p.r, p.r * 0.3, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = c.rim; ctx.beginPath(); ctx.ellipse(0, 0, p.r, p.r * 0.28, 0, 0, Math.PI * 2); ctx.fill();
  const inner = ctx.createRadialGradient(-p.r * 0.2, -4, 4, 0, 0, p.r * 0.92);
